from decimal import Decimal, ROUND_HALF_EVEN
from ledger.currency import CurrencyPrecisionError, MIN_FEE_CENTS, MAX_FEE_CENTS

def calculate_settlement(amount: Decimal, fee_rate: Decimal) -> Decimal:
    if isinstance(amount, float) or isinstance(fee_rate, float):
        raise CurrencyPrecisionError('Float arithmetic is strictly forbidden')
    if amount < Decimal('0'):
        raise CurrencyPrecisionError('Amount cannot be negative')
    raw_fee = (amount * fee_rate).quantize(Decimal('1'), rounding=ROUND_HALF_EVEN)
    fee = max(MIN_FEE_CENTS, min(MAX_FEE_CENTS, raw_fee))
    return amount + fee

