import sys
from datetime import datetime, timezone, timedelta

def load_module(sol_dir):
    sys.path.insert(0, sol_dir)
    for m in ['telemetry.exceptions', 'telemetry.ingest', 'telemetry']:
        if m in sys.modules: del sys.modules[m]
    import telemetry.ingest as ti
    import telemetry.exceptions as te
    return ti, te

def run_test(sol_dir='.'):
    ti, te = load_module(sol_dir)
    ref = datetime(2024, 6, 1, 12, 0, 0, tzinfo=timezone.utc)
    ev_valid = {'event_id': 'ev_1', 'timestamp': '2024-06-01T12:02:00Z', 'payload': {'val': 42}}
    res = ti.validate_and_normalize_event(ev_valid, ref)
    assert res['event_id'] == 'ev_1'
    assert res['timestamp'] == '2024-06-01T12:02:00Z'
    # Naive timestamp test
    try:
        ti.validate_and_normalize_event({'event_id': 'ev_2', 'timestamp': datetime(2024, 6, 1, 12, 0, 0), 'payload': {}}, ref)
        assert False, 'Naive datetime should raise NonUTCError'
    except te.NonUTCError:
        pass
    # Non-UTC timezone test
    tz_est = timezone(timedelta(hours=-5))
    try:
        ti.validate_and_normalize_event({'event_id': 'ev_3', 'timestamp': datetime(2024, 6, 1, 7, 0, 0, tzinfo=tz_est), 'payload': {}}, ref)
        assert False, 'Non-UTC timezone should raise NonUTCError'
    except te.NonUTCError:
        pass
    # Excessive skew test
    ev_skewed = {'event_id': 'ev_4', 'timestamp': '2024-06-01T12:10:00Z', 'payload': {}}
    try:
        ti.validate_and_normalize_event(ev_skewed, ref)
        assert False, 'Excessive skew should raise ClockSkewError'
    except te.ClockSkewError:
        pass

if __name__ == '__main__':
    sol_dir = sys.argv[1] if len(sys.argv) > 1 else '.'
    run_test(sol_dir)
    print('PASS')

