from config.errors import ImmutableConfigViolationError, RESERVED_ROOT_SECTIONS

class FrozenConfigNode:
    def __init__(self, mapping: dict):
        self._data = {}
        for k, v in mapping.items():
            if isinstance(v, dict):
                self._data[k] = FrozenConfigNode(v)
            else:
                self._data[k] = v

    def __getitem__(self, key):
        return self._data[key]

    def __getattr__(self, name):
        if name in self._data:
            return self._data[name]
        raise AttributeError(f'No config attribute {name}')

    def __setitem__(self, key, value):
        raise ImmutableConfigViolationError('FrozenConfigNode is deeply immutable')

    def __setattr__(self, name, value):
        if name == '_data':
            super().__setattr__(name, value)
        else:
            raise ImmutableConfigViolationError('FrozenConfigNode is deeply immutable')

    def __delitem__(self, key):
        raise ImmutableConfigViolationError('FrozenConfigNode is deeply immutable')

    def get(self, key, default=None):
        return self._data.get(key, default)

    def __iter__(self):
        return iter(self._data)

    def __len__(self):
        return len(self._data)

def freeze_configuration(data: dict) -> FrozenConfigNode:
    for k in data.keys():
        if k not in RESERVED_ROOT_SECTIONS:
            raise ValueError(f'Invalid root section {k}')
    return FrozenConfigNode(data)

