from cache.constants import (
    InvalidPriorityError,
    DEFAULT_CAPACITY,
    PRIORITY_HIGH,
    PRIORITY_NORMAL,
    PRIORITY_LOW,
    VALID_PRIORITIES,
)

class PriorityLruCache:
    def __init__(self, capacity: int = DEFAULT_CAPACITY, on_evict=None):
        self.capacity = capacity
        self.on_evict = on_evict
        self._entries = {}
        self._clock = 0

    def put(self, key: str, value, priority: int = PRIORITY_NORMAL):
        if priority not in VALID_PRIORITIES:
            raise InvalidPriorityError(f'Invalid priority {priority}')
        self._clock += 1
        if key in self._entries:
            self._entries[key] = [value, priority, self._clock]
            return
        if len(self._entries) >= self.capacity:
            evict_key = min(
                self._entries.keys(),
                key=lambda k: (self._entries[k][1], self._entries[k][2]),
            )
            ev_val, ev_prio, _ = self._entries.pop(evict_key)
            if self.on_evict:
                self.on_evict(evict_key, ev_val, ev_prio)
        self._entries[key] = [value, priority, self._clock]

    def get(self, key: str, default=None):
        if key not in self._entries:
            return default
        self._clock += 1
        self._entries[key][2] = self._clock
        return self._entries[key][0]

    def size(self) -> int:
        return len(self._entries)
